import axiosConfig from "../axiosConfig"
export const apiGetPlasmidInfo = async (file) => {
    try {
        const formData = new FormData();
        formData.append('fasta', file);

        const response = await axiosConfig.post('/api/plasmid/getplasmidinfo', formData, {
            headers: {
                'Content-Type': 'multipart/form-data',
            },
            params: { sample_id },
        });
        return response.data;
    } catch (error) {
        throw error.response?.data || error.message;
    }
};

export const apiSavePlasmidInfo = async (sample_id, result) => {
    try {
        const response = await axiosConfig.post('/api/plasmid/saveplasmidinfo', result, {
            headers: {
                'Content-Type': 'multipart/form-data',
            },
            params: { sample_id },
        });

        return response.data;
    } catch (error) {
        throw error.response?.data || error.message;
    }
};
